solution.code:
// In Next.js: Pricing.module.css -> .title { color: crimson; font-size: 28px; }
// import styles from './Pricing.module.css';
function App() {
  // Simulating the hashed, scoped class the Module would produce:
  const styles = { title: 'Pricing_title__a1b2c' };
  const scoped = { color: 'crimson', fontSize: 28, margin: 0 };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2 className={styles.title} style={scoped}>Pricing</h2>
      <h2 style={{ margin: 0 }}>Unrelated section is unaffected now</h2>
    </div>
  );
}

